WITH exploded AS (SELECT id, plan, effective_from, currency, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_prices) x AS element) SELECT DATE_TRUNC('QUARTER', effective_from) AS quarter_start, MAX(element) FILTER (WHERE plan = 'enterprise') AS enterprise_max_element, COUNT_IF(currency = 'THB') AS thb_events, COUNT_IF(plan = 'basic') AS basic_events FROM exploded GROUP BY 1 HAVING enterprise_max_element >= 0
